<?php
namespace App\Http\Controllers;use App\Models\ReviewCycle;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class ReviewCycleController extends Controller{public function index(Request $r){$q=ReviewCycle::latest();$q->when($r->search,fn($q,$v)=>$q->where(fn($q)=>$q->where('name','like',"%$v%")->orWhere('description','like',"%$v%")))->when($r->frequency,fn($q,$v)=>$q->where('frequency',$v))->when($r->status!==null&&$r->status!=='',fn($q)=>$q->where('status',$r->status));return view('review-cycles.index',['cycles'=>$q->paginate(10)->withQueryString()]);}public function store(Request $r){ReviewCycle::create($this->data($r));return back()->with('success','Review cycle created successfully.');}public function update(Request $r,ReviewCycle $reviewCycle){$reviewCycle->update($this->data($r,$reviewCycle->id));return back()->with('success','Review cycle updated successfully.');}public function toggle(ReviewCycle $reviewCycle){$reviewCycle->update(['status'=>!$reviewCycle->status]);return back()->with('success','Review cycle status updated.');}public function destroy(ReviewCycle $reviewCycle){$reviewCycle->delete();return back()->with('success','Review cycle deleted.');}private function data(Request $r,$id=null){return $r->validate(['name'=>['required','string','min:2','max:191',Rule::unique('review_cycles')->ignore($id)],'frequency'=>'required|in:Monthly,Quarterly,Semi-Annual,Annual,Custom','description'=>'nullable|string|max:1000','status'=>'required|boolean']);}}
